function makeMissionMarker(pos,color=0x65b7ef){const p={pos:new THREE.Vector3(pos[0],.85,pos[1]),done:false,model:null};marker(p,color);missionProps.push(p);return p}
function clearMission(){missionProps.forEach(p=>{if(p.model)scene.remove(p.model)});enemies.forEach(e=>scene.remove(e.group));missionProps=[];enemies=[]}
