function finishMissionProp(p){if(!p||p.done)return;p.done=true;if(p.model)p.model.visible=false;updateObjective();if(missionProps.every(q=>q.done)){showToast('OBJECTIVE COMPLETE');setTimeout(()=>beginChapter(campaignStage+1),1100)}}

