132: function beginChapter(n){campaignStage=n;clearMission();if(n>=chapters.length){campaignStage=chapters.length;showToast('DAWN OVER GOTHAM — CAMPAIGN COMPLETE');$('#ending').classList.add('show');return}const c=chapters[n];gothamActive=true;cave.visible=false;city.visible=true;scene.fog=new THREE.FogExp2(0x090d12,.012);player.position.set(0,0,7);alfred.position.set(-5,0,7);car.position.set(0,.2,3.8);car.rotation.y=0;city.add(car);batmanActive=true;bruceModel.visible=false;batmanModel.visible=true;if(c.mode==='combat'){const spots=[[-6,-4],[3,-7],[7,2],[-4,6],[0,-12]];for(let i=0;i<c.count;i++)spawnEnemy(...spots[i%spots.length])}else if(c.mode==='intel'){const spots=[[-8,-2],[0,-8],[7,1],[-4,7],[5,-11],[9,-5]];for(let i=0;i<c.count;i++)makeMissionMarker(spots[i%spots.length],0x64c6ff)}else if(c.mode==='drive'){const route=[[8,-6],[5,4],[-6,7],[-8,-8]];for(let i=0;i<c.count;i++)makeMissionMarker(route[i%route.length],0xffc45d)}else missionProps.push({pos:alfred.position.clone(),done:false,kind:'contact'});updateObjective();showToast(`CHAPTER ${String(n+1).padStart(2,'0')} — ${c.title.toUpperCase()} · GOTHAM CITY`)}
133: function finishMissionProp(p){if(!p||p.done)return;p.done=true;if(p.model)p.model.visible=false;updateObjective();if(missionProps.every(q=>q.done)){showToast('OBJECTIVE COMPLETE');setTimeout(()=>beginChapter(campaignStage+1),1100)}}
