184: function activateItem(item){if(!item||item.done)return;if(item.id==='lift'&&items.some(i=>i.id!=='lift'&&!i.done)){startDialogue([['ALFRED','Not quite yet, sir. There are still tools to check. Follow the markers.']]);return}item.done=true;item.model.visible=false;collected++;if(item.id==='book'){showToast('FIELD GUIDE ADDED');startDialogue([['BRUCE','A place to start. Discipline before anything else.'],['ALFRED','An excellent instinct, sir. The rest is just equipment.']])}else if(item.id==='suit'){showToast('SUIT SYSTEMS ONLINE');startDialogue([['ALFRED','The suit should fit. I adjusted the shoulders. You do brood rather unevenly.'],['BRUCE','I’ll try to brood more symmetrically.']])}else if(item.id==='car'){showToast('VEHICLE BAY — READY');startDialogue([['ALFRED','A prototype. It is not quite street legal.'],['BRUCE','Is it safe?'],['ALFRED','I think we can agree that is not the primary concern.']])}else if(item.id==='lift'){beginChapter(0);return}else{showToast(item.name.toUpperCase()+' ADDED');startDialogue([['BRUCE',item.name+'—ready.'],['ALFRED','Take care with it, sir. A tool is only as good as the person holding it.']])}updateObjective()}
185: function interact(){if(dialogueBusy){nextLine();return}if(inCar){inCar=false;player.visible=true;player.position.copy(car.position).add(new THREE.Vector3(1.7,0,0));showToast('EXITED THE BATMOBILE');return}if(!interactTarget)return;if(interactTarget.id)activateItem(interactTarget);else if(interactTarget.kind==='contact'){finishMissionProp(interactTarget);startDialogue([['ALFRED','The evacuation is underway, sir. Gotham is safer when we remember we are not alone.']])}else if(interactTarget.mission)finishMissionProp(interactTarget.mission);else if(interactTarget.car){inCar=true;player.visible=false;showToast('BATMOBILE — W A S D TO DRIVE · E TO EXIT')}}
186: function toggleSuit(){if(inCar)return;batmanActive=!batmanActive;bruceModel.visible=!batmanActive;batmanModel.visible=batmanActive;showToast(batmanActive?'BATMAN SUIT ON':'BRUCE WAYNE')}function attack(){if(!gameActive||inCar||!batmanActive||attackCooldown>0)return;attackCooldown=.48;let target=null,best=2.3;for(const e of enemies){if(e.done)continue;const d=player.position.distanceTo(e.group.position);if(d<best){best=d;target=e}}if(!target){showToast('NO TARGET IN RANGE');return}target.hits++;target.group.rotation.y+=.3;if(target.hits>=2){finishMissionProp(target);showToast('THUG DISARMED')}else showToast('STRIKE — ONE MORE HIT')}
187: $('#touchInteract').onclick=interact;$('#touchTransform').onclick=toggleSuit;$('#touchAttack').onclick=attack;
