// Opening cinematic and mode selection
let cinemaTimer=0,cinemaTimeouts=[];
function finishCinematic(){
  if(!$('#cinematic').classList.contains('show'))return;
  cinemaTimeouts.forEach(clearTimeout);cinemaTimeouts=[];
  $('#cinematic').classList.add('fadeOut');
  setTimeout(()=>{$('#cinematic').style.display='none';$('#modeScreen').classList.add('show')},700);
}
function runCinematic(){
  $('#cinematic').classList.add('show');
  const beats=[
    [0,'GOTHAM CITY · 2:14 AM'],[900,'Three criminals corner a witness beneath the rain.'],
    [2200,'BATMAN ARRIVES'],[3400,'The first strike ends the alley fight.'],
    [4700,'A green grin waits above the rooftops.'],[6000,'Joker laughs. Batman falls toward him.'],
    [7600,'The laughing stops.']
  ];
  beats.forEach(([ms,text])=>cinemaTimeouts.push(setTimeout(()=>{$('#cinemaCaption').textContent=text},ms)));
  cinemaTimeouts.push(setTimeout(()=>{document.querySelector('.cinemaThug.thugOne').classList.add('down')},3200));
  cinemaTimeouts.push(setTimeout(()=>{document.querySelector('.cinemaThug.thugTwo').classList.add('down')},3900));
  cinemaTimeouts.push(setTimeout(()=>document.querySelector('.cinemaJoker').classList.add('knocked'),7000));
  cinemaTimeouts.push(setTimeout(finishCinematic,8500);
}
$('#cinemaSkip').onclick=finishCinematic;
function startSelectedMode(mode){
  gameMode=mode;$('#modeScreen').classList.remove('show');$('#hud').style.display='block';gameActive=true;
  if(mode==='story'){
    $('#story').classList.add('show');beat=0;renderBeat();
  }else if(mode==='campaign'){
    $('#title').style.display='none';$('#story').classList.remove('show');
    startDialogue([['ALFRED','The Batcave is ready, sir. Explore it fully, then use the elevator.']]);
    showToast('CAMPAIGN — EQUIP THE BATCAVE');
  }else if(mode==='training'){
    city.visible=true;cave.visible=false;gothamActive=true;batmanActive=true;bruceModel.visible=false;batmanModel.visible=true;
    player.position.set(0,0,7);clearMission();makeMissionMarker([-6,-4],0x64c6ff);makeMissionMarker([6,-4],0xffc45d);makeMissionMarker([0,-10],0x64c6ff);
    $('#chapterLabel').textContent='TRAINING — GOTHAM RANGE';$('#objectiveTitle').textContent='Movement drill';$('#objectiveText').textContent='Visit the three markers. Press R for the suit and F for combat.';
    showToast('TRAINING — PRESS E AT EACH MARKER');
  }else if(mode==='bots'){
    city.visible=true;cave.visible=false;gothamActive=true;clearMission();campaignStage=-1;
    batmanActive=true;bruceModel.visible=false;batmanModel.visible=true;player.position.set(-5,0,0);playerHealth=100;
    spawnEnemy(5,0);spawnEnemy(7,3);enemies.forEach((e,i)=>{if(i===0){e.botOpponent=true;e.group.scale.setScalar(1.12)}});
    $('#chapterLabel').textContent='FREEPLAY — 1V1';$('#objectiveTitle').textContent='Gotham showdown';$('#objectiveText').textContent='Defeat the bot opponent. F to strike, R to switch suits.';
    showToast('1V1 — ADAPTIVE BOT ACTIVE');
  }
  updateObjective();
}
document.querySelectorAll('.modeCard').forEach(card=>card.addEventListener('click',()=>startSelectedMode(card.dataset.mode)));
runCinematic();

